// Some portions generated by Codex
package org.eclipse.rdf4j.sail.inferencer.fc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategyFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.NotifyingSail;
import org.eclipse.rdf4j.sail.inferencer.InferencerConnection;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class BuiltInInferencerGraphAlgebraTest {

	enum Stack {
		SCHEMA,
		DEDUPING,
		DIRECT_TYPES,
		NESTED
	}

	@ParameterizedTest
	@EnumSource(Stack.class)
	void builtInStacksPreserveGraphScopeAndExplicitLegacy(Stack kind) {
		SailRepository repository = new SailRepository(stack(kind, new MemoryStore()));
		try (var connection = repository.getConnection()) {
			var vf = repository.getValueFactory();
			var graphName = vf.createIRI("urn:data");
			connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createLiteral("value"), graphName);
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT ?g WHERE { GRAPH ?g {} }", null);
			assertEquals(GraphAlgebraMode.GRAPH, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var rows = query.evaluate()) {
				assertTrue(rows.hasNext());
				assertEquals(graphName, rows.next().getValue("g"));
				assertFalse(rows.hasNext());
			}
			String absent = "SELECT ?x WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }";
			try (var rows = connection.prepareTupleQuery(absent).evaluate()) {
				assertFalse(rows.hasNext());
			}
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			try (var rows = connection.prepareTupleQuery(absent).evaluate()) {
				assertTrue(rows.hasNext());
				assertEquals("1", rows.next().getValue("x").stringValue());
				assertFalse(rows.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(Stack.class)
	void wrappedCustomEvaluatorRetainsLegacyDefault(Stack kind) {
		MemoryStore base = new MemoryStore();
		base.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory() {
		});
		SailRepository repository = new SailRepository(stack(kind, base));
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL,
					"SELECT ?x WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }", null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void unknownInferencerConnectionSubclassesDoNotInheritGraphOptIn() {
		MemoryStore base = new MemoryStore();
		base.init();
		try (var connection = base.getConnection()) {
			InferencerConnection delegate = (InferencerConnection) connection;
			assertFalse(new DedupingInferencerConnection(delegate, base.getValueFactory()) {
			}.supportsGraphAlgebra());
			assertFalse(new SchemaCachingRDFSInferencerConnection(new SchemaCachingRDFSInferencer(base), delegate) {
			}.supportsGraphAlgebra());
		} finally {
			base.shutDown();
		}
	}

	private static NotifyingSail stack(Stack kind, MemoryStore base) {
		return switch (kind) {
		case SCHEMA -> new SchemaCachingRDFSInferencer(base);
		case DEDUPING -> new DedupingInferencer(base);
		case DIRECT_TYPES -> new DirectTypeHierarchyInferencer(base);
		case NESTED -> new DedupingInferencer(new DirectTypeHierarchyInferencer(new SchemaCachingRDFSInferencer(base)));
		};
	}
}
